(* [comment removed for export] *)
Lemma errno_cells : forall M : word -> option byte, exists ev, rw_cells rsegs M 886700 [C4 ev].
Proof.
  intros M.
  set (f := fun i : nat => match mrd rsegs M (wa (886700 + Z.of_nat i)) with Some b => b | None => Z_to_bv 8 0 end).
  assert (RD : forall i, (i < 4)%nat -> mrd rsegs M (wa (886700 + Z.of_nat i)) = Some (f i)).
  { intros i Hi. unfold f, mrd.
    assert (Ei : (i = 0 \/ i = 1 \/ i = 2 \/ i = 3)%nat) by lia.
    destruct (M (wa (886700 + Z.of_nat i))) as [b|]; [reflexivity|].
    destruct Ei as [-> | [-> | [-> | ->]]]; vm_compute; reflexivity. }
  exists (Z_to_bv 64 (bytes_le_to_Z [f 0%nat; f 1%nat; f 2%nat; f 3%nat])).
  assert (L4 : le4 (Z_to_bv 64 (bytes_le_to_Z [f 0%nat; f 1%nat; f 2%nat; f 3%nat])) = [f 0%nat; f 1%nat; f 2%nat; f 3%nat]).
  { unfold le4. pose proof (WdWkMem.bytes_le_to_Z_range [f 0%nat; f 1%nat; f 2%nat; f 3%nat]) as R. 
    change (2 ^ (8 * Z.of_nat (length [f 0%nat; f 1%nat; f 2%nat; f 3%nat]))) with (2 ^ 32) in R.
    rewrite unsigned_small64 by lia. apply (WdWkMem.Z_to_le_bytes_inv [f 0%nat; f 1%nat; f 2%nat; f 3%nat]). }
  split; [split|].
  - cbn. auto.
  - cbn [cells_bytes cbytes]. rewrite app_nil_r, L4. split; [lia|]. split; [cbn; lia|].
    intros i Hi. cbn [length] in Hi. rewrite RD by lia.
    assert (Ei : (i = 0 \/ i = 1 \/ i = 2 \/ i = 3)%nat) by lia. destruct Ei as [-> | [-> | [-> | ->]]]; reflexivity.
  - cbn [cells_size csize Nat.add]. split; [lia|]. split; [lia|]. intros i Hi. unfold wview.
    destruct (M (wa (886700 + i))) as [b|]; [discriminate|].
    assert (Ei : i = 0 \/ i = 1 \/ i = 2 \/ i = 3) by lia. destruct Ei as [-> | [-> | [-> | ->]]]; vm_compute; discriminate.
Qed.

(* [comment removed for export] *)
Lemma u8ro_of_L5 M (a : Z) (l : list Z) : L5.bytes_at rsegs M a l -> 0 <= a -> a + Z.of_nat (length l) <= 2 ^ 64 -> u8ro rsegs M a (map (Z_to_bv 8) l).
Proof.
  intros B Ha Hl. split; [exact Ha|]. split; [rewrite length_map; exact Hl|].
  intros i Hi. rewrite length_map in Hi. specialize (B i Hi). unfold L5.u8_at in B. rewrite rdn_unfold in B. fold (wa (a + Z.of_nat i)) in B.
  destruct (mrd rsegs M (wa (a + Z.of_nat i))) as [b|]; [|discriminate]. cbn in B.
  injection B as E. subst b.
  erewrite map_nth_error by (apply nth_error_nth'; exact Hi). reflexivity.
Qed.
Lemma L5_of_u8ro M (a : Z) (l : list Z) : u8ro rsegs M a (map (Z_to_bv 8) l) -> L5.bytes_at rsegs M a l.
Proof.
  intros (Ha & Hl & B) i Hi. unfold L5.u8_at. rewrite rdn_unfold. change (Z_to_bv 64 (a + Z.of_nat i)) with (wa (a + Z.of_nat i)).
  rewrite length_map in Hl. specialize (B i ltac:(rewrite length_map; exact Hi)). erewrite map_nth_error in B by (apply nth_error_nth'; exact Hi).
  rewrite B. rewrite rdn_unfold. reflexivity.
Qed.

Section Bridge.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.
Variable L : heap_layout.
Hypothesis LY : PMS.layout L.

Theorem strtod_ok : WDL.strtod_spec RSEGS AD L 0xb8c20.
Proof.
  intros fx R M model K s endp n sp r bs MOK K0 ES R10 R11 Hlen Hn GR BT FRM S1 S2 E1 E2 DEF DJ BOK CONT.
  destruct ES as (R1 & RA & R2 & R3 & R4 & ST).
  destruct ST as (AL & FLO & SPT & WIN & SDEF).
  destruct MOK as (Hh & Hl & Hm).
  destruct RA as (Rr & Er).
  pose proof BOK as (IMG & (canary & Rc & CAN) & NL & LL).
  unfold WDL.STRTOD_SCR, WDL.SNP_MAX in *.
  assert (MI : mem_inv rsegs M) by (apply mem_inv_of_base; exact IMG).
  assert (STK : stk rsegs M (sp - 10240) sp).
  { apply stk_of_defined; [lia | lia |]. replace (sp - (sp - 10240)) with 10240 by lia. exact SDEF. }
  set (bz := map (Z_to_bv 8) (bs ++ [0])).
  assert (Lbz : length bz = S (length bs)) by (subst bz; rewrite length_map, length_app; cbn; lia).
  assert (TXT : u8ro rsegs M s bz) by (subst bz; apply u8ro_of_L5; [exact BT | lia | rewrite length_app; cbn [length]; lia]).
  assert (GT : gtext bz) by (subst bz; apply (gtext_of_gnum bs); [exact GR | lia]).
  assert (ENDe : exists eold, rw_cells rsegs M endp [C8 eold]).
  { assert (WR : wr_at rsegs M endp 8).
    { split; [lia|]. split; [lia|]. intros i Hi.
      assert (Hwa : bv_unsigned (wa (endp + i)) = endp + i) by (unfold wa; rewrite Z_to_bv_unsigned; apply bv_wrap_small; unfold bv_modulus; lia).
      rewrite ref_wview_overlay by (rewrite Hwa; lia). apply (DEF i Hi). }
    destruct (rwr_at_bytes_exist M endp 8 WR ltac:(lia) ltac:(lia)) as (obuf & Lo & Bo).
    assert (U8 : u8arr rsegs M endp obuf) by (split; [exact Bo | rewrite Lo; exact WR]).
    pose proof (rw_cells_of_u8arr rsegs M endp obuf U8) as RC. rewrite Lo in RC.
    destruct (rw_cb8_c8 M endp [] obuf [] RC) as [w Hw]. exists w. exact Hw. }
  destruct ENDe as (eold & END).
  destruct (errno_cells M) as (ev & ER).
  assert (CANc : ro_cells rsegs M 0xf8ac0 [C8 (Z_to_bv 64 canary)]).
  { split; [cbn; auto|]. cbn [cells_bytes cbytes]. rewrite app_nil_r. apply bytes_at_of_rdn; [| lia | cbn; lia]. exact CAN. }
  assert (GOT : ro_cells rsegs M 0xc5ab8 [C8 (Z_to_bv 64 0xf8ac0)]).
  { split; [cbn; auto|]. cbn [cells_bytes cbytes]. rewrite app_nil_r. split; [lia|]. split; [cbn; lia|].
    intros i Hi. cbn [length] in Hi. unfold mrd.
    assert (Ei : (i = 0 \/ i = 1 \/ i = 2 \/ i = 3 \/ i = 4 \/ i = 5 \/ i = 6 \/ i = 7)%nat) by (cbn in Hi; lia).
    rewrite (IMG (0xc5ab8 + Z.of_nat i)) by (cbn [pa_rw_lo AD]; lia).
    destruct Ei as [-> | [-> | [-> | [-> | [-> | [-> | [-> | ->]]]]]]]; vm_compute; f_equal; apply bv_eq; reflexivity. }
  rewrite <- (bv5_lit 1 ltac:(lia)) in R1. rewrite <- (bv5_lit 2 ltac:(lia)) in R2. rewrite <- (bv5_lit 4 ltac:(lia)) in R4.
  rewrite <- (bv5_lit 10 ltac:(lia)) in R10. rewrite <- (bv5_lit 11 ltac:(lia)) in R11.
  assert (U1 : bv_unsigned (getr R (Z_to_bv 5 1)) = r) by (rewrite R1; apply u64_small; lia).
  assert (U2 : bv_unsigned (getr R (Z_to_bv 5 2)) = sp) by (rewrite R2; apply u64_small; lia).
  assert (U4 : bv_unsigned (getr R (Z_to_bv 5 4)) = 0xd8850) by (rewrite R4; apply u64_small; cbn; lia).
  replace 886700 with (bv_unsigned (getr R (Z_to_bv 5 4)) + -164) in ER by lia.
  pose proof (strtod_walk (getr R (Z_to_bv 5 1)) (getr R (Z_to_bv 5 2)) (getr R (Z_to_bv 5 3)) (getr R (Z_to_bv 5 4))
                (getr R (Z_to_bv 5 5)) (getr R (Z_to_bv 5 6)) (getr R (Z_to_bv 5 7)) (getr R (Z_to_bv 5 8)) (getr R (Z_to_bv 5 9))
                (getr R (Z_to_bv 5 10)) (getr R (Z_to_bv 5 11)) (getr R (Z_to_bv 5 12)) (getr R (Z_to_bv 5 13)) (getr R (Z_to_bv 5 14))
                (getr R (Z_to_bv 5 15)) (getr R (Z_to_bv 5 16)) (getr R (Z_to_bv 5 17)) (getr R (Z_to_bv 5 18)) (getr R (Z_to_bv 5 19))
                (getr R (Z_to_bv 5 20)) (getr R (Z_to_bv 5 21)) (getr R (Z_to_bv 5 22)) (getr R (Z_to_bv 5 23)) (getr R (Z_to_bv 5 24))
                (getr R (Z_to_bv 5 25)) (getr R (Z_to_bv 5 26)) (getr R (Z_to_bv 5 27)) (getr R (Z_to_bv 5 28)) (getr R (Z_to_bv 5 29))
                (getr R (Z_to_bv 5 30)) (getr R (Z_to_bv 5 31))
                (@fp_regs fx) (@fp_csr fx) M (sp - 10240) s endp bz (Z_to_bv 64 canary) ev eold) as EVT.
  rewrite U1, U2, U4 in EVT. rewrite U4 in ER.
  specialize (EVT MI STK ltac:(lia) ltac:(lia) ltac:(lia) ltac:(rewrite Lbz; lia) Er ltac:(lia) GOT CANc ER TXT GT END ltac:(lia) ltac:(rewrite Lbz; lia) ltac:(lia) FRM R10 R11).
  change (mkR _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) with (canon_regs R) in EVT at 2.
  apply evt_grows in EVT.
  destruct (evt_eqv_transfer rsegs _ _ (@mkst fx R (Z_to_bv 64 0xb8c20) M (seg_rom rsegs)) (mkst_eqv_canon R _ M _) EVT)
    as (ms1 & ms1' & (PO & GRW) & EQV & Hms).
  destruct PO as (t0x & t1x & t2x & a0x & a1x & a2x & a3x & a4x & a5x & a6x & a7x & t3x & t4x & t5x & t6x & F2 & fc2 & m2 & ev2 & -> & FK & FZ2 & MU2 & WM2 & MI2 & ST2 & END2 & TXT2 & CAN2 & ER2).
  change (ms_mem (MS _ _ _ _ _ ?mm _)) with mm in GRW.
  unfold PMSP.cfg. eapply srz_msteps; [exact Hh | exact Hl | exact Hms |].
  pose proof (FRMA.msteps_frm_keep_s _ _ Hms) as FRK.
  destruct (ms_eqv_MS_inv _ _ _ _ _ _ _ EQV) as [EQ REQ]. rewrite EQ in FRK |- *. clear EQ.
  assert (RPC : ret_pc (getr R (Z_to_bv 5 1)) = Z_to_bv 64 r).
  { rewrite R1. apply ret_pc_even; [lia | exact Er]. }
  rewrite RPC in *.
  change (MS (ms_regs ms1') F2 (Z_to_bv 64 r) fc2 None m2 (seg_rom rsegs)) with (@mkst (mkFP F2 fc2) (ms_regs ms1') (Z_to_bv 64 r) m2 (seg_rom rsegs)).
  pose proof (PMS.ly_errno L LY) as LE.
  assert (FRAME : forall x : word, ~ (sp - 10240 <= bv_unsigned x < sp) -> ~ (endp <= bv_unsigned x < endp + 8) -> ~ (886700 <= bv_unsigned x < 886704) -> m2 x = M x).
  { intros x H1 H2 H3. apply MU2. cbn [outside]. repeat split; lia. }
  apply (CONT (mkFP F2 fc2) (ms_regs ms1') m2).
  - eapply regs_preserved_canon. exact REQ.
  - split.
    + intros rr Hrr. cbn [fp_regs]. unfold getr. destruct (bv_eqb rr 0) eqn:E0; [reflexivity|]. apply FK. unfold fcs_idx. exact Hrr.
    + cbn [fp_csr]. exact FRK.
  - (* [comment removed for export] *)
    destruct END2 as [[_ B] _]. cbn [cells_bytes cbytes] in B. rewrite app_nil_r in B.
    unfold L5.u64_at. pose proof (bytes_at_rdn rsegs m2 endp _ 0 8 B ltac:(rewrite length_le8; lia)) as RD. rewrite Z.add_0_r in RD.
    change (Z_to_bv 64 endp) with (wa endp). rewrite RD. cbn [firstn skipn]. f_equal.
    replace (s + Z.of_nat (length bz) - 1) with (s + n) by (rewrite Lbz; lia). unfold le8. rewrite firstn_all2 by (rewrite length_le8; lia). reflexivity.
  - (* [comment removed for export] *) subst bz. apply L5_of_u8ro. exact TXT2.
  - (* [comment removed for export] *)
    split; [|split].
    + intros a Ha Hs Ho He. apply FRAME.
      * rewrite u64_small by lia. lia.
      * rewrite u64_small by lia. intros Hin. apply (Ho (endp, 8)); [left; reflexivity|]. unfold L5.in_rng. cbn [fst snd]. lia.
      * rewrite u64_small by lia. intros Hin. apply He. unfold in_errno. rewrite LE. lia.
    + exact GRW.
    + intros i Hi. apply GRW. apply SDEF. exact Hi.
  - (* [comment removed for export] *)
    assert (LOW : forall i, 0 <= i < 0xfa000 -> ~ (886700 <= i < 886704) -> m2 (Z_to_bv 64 i) = M (Z_to_bv 64 i)).
    { intros i Hi Hne. apply FRAME; rewrite u64_small by lia; lia. }
    split; [|split; [|split]].
    + intros i Hi. rewrite LOW by (cbn [pa_rw_lo AD] in Hi; lia). apply IMG. exact Hi.
    + exists canary. split; [exact Rc|]. unfold L5.u64_at in *. rewrite <- CAN.
      apply (L5C.rdn_agree RSEGS M m2 8%nat (pa_canary AD)); [cbn [pa_canary AD]; lia | cbn [pa_canary AD]; lia |].
      intros i Hi. apply LOW; cbn [pa_canary AD] in Hi; lia.
    + intros i Hi. rewrite LOW by (cbn [pa_need_locks AD] in Hi; lia). apply NL. exact Hi.
    + intros i Hi. rewrite LOW by (cbn [pa_locale_lock AD] in Hi; lia). apply LL. exact Hi.
Qed.
